@idl.struct.basic_example:
@idl.struct
class MyType:
    name: str = ""
    value: int = 0
    active: bool = False

@idl.struct.bounded_string_example:
@idl.struct(
    member_annotations={
        'name': [idl.bound(64)],
        'description': [idl.bound(256)],
    }
)
class MyType:
    name: str = ""
    description: str = ""
    value: int = 0
